items={
53:('ساعت','بتواند زمان را به دو شیوه بیان و یک ربع/نیم ساعت پس یا پیش از زمان داده‌شده را روی ساعت نشان دهد.','ادامهٔ مرور فصل ۳: خواندن/رسم زمان ساعت‌ها و ساخت الگوی هندسی در شبکه؛ زمانِ عقربهٔ چاپی نیازمند مشاهدهٔ شکل است.'),
54:('تانگرام','بتواند شکل داده‌شده را با خط‌های مناسب به شمار خواسته‌شده از قسمت‌های مساوی تقسیم کند.','معمّای تقسیم چند شکل به قسمت‌های مساوی؛ فرهنگ خواندن دربارهٔ قطعات تانگرام؛ شکل‌های حل‌شده هنوز بازبینی تصویری ندارند.'),
127:('هوا','بتواند کاربرد جمع‌آوری داده‌های آب‌وهوا را برای پیش‌بینی با یک نمونه توضیح دهد.','آغاز فصل آمار و نمودار با تصویر انواع کتاب/کارهای روزانه و پرسش کاربرد آمار برای پیش‌بینی هوا؛ شمار عناصر تصویر مبنای سؤال نیست.'),
128:('فصل','بتواند تعداد تولدها را به تفکیک فصل با چوب‌خط ثبت و فصل پرتعداد/کم‌تعداد را از جدول پیدا کند.','فعالیت سرشماری فصل تولد هم‌کلاسی‌ها و ثبت چوب‌خط؛ ثبت آزمایش چرخنده در جدول جداگانه؛ نتایج وابسته به کلاس‌اند.'),
129:('چوب خط','بتواند شمار چوب‌خط‌های هر روز را به عدد تبدیل و دادهٔ زمانی هفته را مقایسه کند.','کار در کلاس: چوب‌خط ستاره برای کارهای خوب در طول هفته؛ بررسی جدول زمان تکالیف و مطالعهٔ رضا؛ خانه‌های تصویری نیازمند شمارش مستقل‌اند.'),
130:('نماینده','بتواند رأی‌های فهرست‌شده را برای هر نام با چوب‌خط بشمارد و برنده را از جدول تعیین کند.','تمرین رأی نمایندهٔ کلاس؛ سرشماری کتاب‌های رنگیِ قفسه و مقایسهٔ گروه‌ها؛ عددِ رأی یا کتاب از متن به کلید بازی منتقل نمی‌شود.'),
131:('نمودار ستونی','بتواند نتیجهٔ چند آزمایشِ مهره‌کشی را با یک خانه برای هر برداشت در نمودار ستونی نشان دهد.','فعالیت رسم نمودار ستونی از آزمایش کیسه و از زمان درس خواندن در هفته؛ تعداد رخدادهای تصادفی پاسخ ثابت ندارد.'),
132:('123','بتواند قد/وزن هر دانش‌آموز را در بازهٔ مناسب نمودار ستونی قرار دهد.','کار در کلاس: قد ۱۲۳ سانتی‌متری نمونه در بازهٔ ۱۲۰–۱۲۴؛ رنگ‌آمیزی ستون قد و وزنِ واقعی کلاس؛ نتایج کلاس ثابت نیستند.'),
133:('بارانی','بتواند با کم‌کردن روزهای معلوم از چهار هفته، شمار روزهای نیمه‌ابری را حساب و نمودار هوای هفته‌ها را تکمیل کند.','تمرین جدول وضعیت هوا در چهار هفته و نمودار کتاب‌های خوانده‌شده؛ رنگ‌کردن ستون‌ها و شمار نمادها نیازمند بازبینی مستقل است.'),
134:('53','بتواند جای‌خالی تساوی ۲۷+□=۵۳ را با حدس و آزمایش پیدا کند.','حل مسئلهٔ عدد گمشده و مسئلهٔ قیمت دو دفتر و پاک‌کن؛ جعبهٔ «کامل کن» برای دسته‌ها تصویری است و از متن کلیدگذاری نمی‌شود.'),
136:('23','بتواند عدد داده‌شده را به ده‌تایی نزدیک‌تر گرد کند و دادهٔ تقریبی را در نمودار تصویری ده‌تایی نشان دهد.','فعّالیت تقریب به ده و جدول شمار دانش‌آموزان کلاس‌های اوّل تا ششم؛ هر نماد نمودار نمایندهٔ ۱۰ دانش‌آموز است.'),
137:('مدرسه','بتواند دادهٔ شمار دانش‌آموزان کلاس‌های مدرسه را به مقدار تقریبی تبدیل و برای هر ده‌تا یک نماد بگذارد.','کار در کلاس: پرسیدن شمار کلاس‌های مدرسهٔ خود و رسم نمودار تصویری؛ جدول خانه‌های خیابان‌ها در فعالیت دوم، بدون حدس خانه‌های خالی.'),
140:('12','بتواند نتیجهٔ ۱۲ چرخش را هم در شکل رنگی و هم در نمودار ستونی نمایش دهد و کاربرد هر نمایش را مقایسه کند.','کار در کلاس آزمایش چرخنده، ثبت رخدادها؛ جعبهٔ الگویابی اعداد فرد/زوج جداست؛ نتیجهٔ آزمایش تصادفی کلید ثابت ندارد.'),
141:('ریاضی','بتواند ساعات درس‌های برنامهٔ هفتگی را با رنگ‌کردن خانه‌های جدول نشان دهد.','تمرین ساخت نمایش رنگی ساعات ریاضی، علوم، قرآن و ورزش؛ مقایسهٔ کارهای روزانهٔ دو دانش‌آموز از نمودار تصویری، بدون حدس ارتفاع ستون‌ها.'),
142:('رنگ','بتواند ترجیح رنگ‌های هم‌کلاسی‌ها را با چوب‌خط در جدول جمع‌آوری و به نمودار ستونی تبدیل کند.','مرور فصل: فرهنگ نوشتن دربارهٔ جدول و نمودار؛ فهرست رنگ‌های پسندیدهٔ کلاس برای تمرین جدولی؛ شمارش دقیق فهرست نیازمند وارسی مستقل است.'),
143:('گوسفند','بتواند شمار گوسفندان را به ده‌تایی نزدیک‌تر گرد کند و هر ۱۰ تا را با یک نماد تصویری نشان دهد.','ادامهٔ پرسش‌های نمودار رنگ از صفحهٔ پیش؛ جدول تعداد گوسفندان و ثبت فعالیت‌های روزانهٔ شخصی در جدول زمان.'),
144:('تقارن','بتواند سطح یک شکل را با قطعه‌های داده‌شده بپوشاند و در طرح کاشی‌کاری به خط تقارن توجه کند.','معمّای پوشاندن شکل با قطعات و خلّق باش کاشی‌کاری متقارن؛ نمونهٔ تصویری، معمای دست‌سازه است نه سؤال عددی موتور.'),
}
